on conflict (id) do update set
  name = excluded.name, emoji = excluded.emoji, portion = excluded.portion, kcal = excluded.kcal,
  protein = excluded.protein, fat = excluded.fat, carbs = excluded.carbs;

on conflict (id) do update set
  type = excluded.type, muscle = excluded.muscle, name = excluded.name, hint = excluded.hint,
  reps = excluded.reps, seconds = excluded.seconds, kcal_per_min = excluded.kcal_per_min;
