insert into public.exercises (id, type, muscle, name, hint, reps, seconds, kcal_per_min) values
  ('e0000000-0000-4000-8000-000000000001', 'home', 'chest', '{"uz":"Yerdan qo‘l bilan ko‘tarilish","ru":"Отжимания","en":"Push-ups"}'::jsonb, '{"uz":"Tanani to‘g‘ri chiziqda tuting, ko‘krak yerga deyarli tegsin.","ru":"Держите тело прямым, опускайтесь почти до касания грудью пола.","en":"Keep your body in a straight line and lower your chest almost to the floor."}'::jsonb, 15, null, 7),
  ('e0000000-0000-4000-8000-000000000002', 'home', 'legs', '{"uz":"O‘tirib-turish","ru":"Приседания","en":"Bodyweight squats"}'::jsonb, '{"uz":"Tovonlar yerdan uzilmasin, tizzalar oyoq uchidan oshmasin.","ru":"Пятки не отрывайте, колени не выводите за носки.","en":"Keep heels down and knees in line with your toes."}'::jsonb, 20, null, 6),
  ('e0000000-0000-4000-8000-000000000003', 'home', 'core', '{"uz":"Planka","ru":"Планка","en":"Plank"}'::jsonb, '{"uz":"Bel egilmasin, qorin mushaklarini tarang tuting.","ru":"Не прогибайте поясницу, держите пресс в напряжении.","en":"Don''t let your lower back sag; brace your abs."}'::jsonb, null, 45, 4.5),
  ('e0000000-0000-4000-8000-000000000004', 'home', 'full_body', '{"uz":"Berpi","ru":"Бёрпи","en":"Burpees"}'::jsonb, '{"uz":"O‘tiring, oyoqlarni orqaga tashlang, qayting va sakrang.","ru":"Присед, упор лёжа, возврат и прыжок вверх.","en":"Squat, kick back to plank, return and jump up."}'::jsonb, 10, null, 10),
  ('e0000000-0000-4000-8000-000000000005', 'home', 'legs', '{"uz":"Hamla (oldinga qadam)","ru":"Выпады","en":"Lunges"}'::jsonb, '{"uz":"Har bir oyoq bilan navbatma-navbat, gavda tik tursin.","ru":"Чередуйте ноги, корпус держите вертикально.","en":"Alternate legs and keep your torso upright."}'::jsonb, 12, null, 6),
  ('e0000000-0000-4000-8000-000000000006', 'home', 'cardio', '{"uz":"Yulduzcha sakrash","ru":"Прыжки «звёздочка»","en":"Jumping jacks"}'::jsonb, '{"uz":"Sakrab oyoqlarni kerib, qo‘llarni boshdan yuqoriga ko‘taring.","ru":"В прыжке разводите ноги и поднимайте руки над головой.","en":"Jump feet apart while raising arms overhead."}'::jsonb, null, 60, 9),
  ('e0000000-0000-4000-8000-000000000007', 'home', 'core', '{"uz":"Alpinist","ru":"Скалолаз","en":"Mountain climbers"}'::jsonb, '{"uz":"Planka holatida tizzalarni tez-tez ko‘krakka torting.","ru":"В планке быстро подтягивайте колени к груди.","en":"From a plank, drive knees to chest quickly."}'::jsonb, null, 40, 9),
  ('e0000000-0000-4000-8000-000000000008', 'home', 'glutes', '{"uz":"Dumba ko‘prigi","ru":"Ягодичный мостик","en":"Glute bridge"}'::jsonb, '{"uz":"Chalqancha yotib, tosni ko‘taring va yuqorida 1 soniya ushlang.","ru":"Лёжа на спине поднимайте таз, задержитесь на 1 секунду.","en":"Lying on your back, lift hips and hold 1 second at the top."}'::jsonb, 15, null, 4),
  ('e0000000-0000-4000-8000-000000000009', 'home', 'cardio', '{"uz":"Arqon sakrash","ru":"Прыжки на скакалке","en":"Jump rope"}'::jsonb, '{"uz":"Oyoq uchida yengil sakrang, arqonni bilaklar bilan aylantiring.","ru":"Прыгайте легко на носках, вращайте кистями.","en":"Bounce lightly on the balls of your feet; turn the rope with your wrists."}'::jsonb, null, 120, 12),
  ('e0000000-0000-4000-8000-000000000010', 'gym', 'chest', '{"uz":"Shtanga bilan jim (skameykada)","ru":"Жим штанги лёжа","en":"Barbell bench press"}'::jsonb, '{"uz":"Kuraklarni birlashtiring, shtangani ko‘krakning pastki qismiga tushiring.","ru":"Сведите лопатки, опускайте гриф к низу груди.","en":"Retract shoulder blades and lower the bar to your lower chest."}'::jsonb, 10, null, 6),
  ('e0000000-0000-4000-8000-000000000011', 'gym', 'back', '{"uz":"Stanovoy tortish","ru":"Становая тяга","en":"Deadlift"}'::jsonb, '{"uz":"Orqa to‘g‘ri, shtanga oyoqlarga yaqin harakatlansin.","ru":"Спина прямая, гриф двигается вдоль ног.","en":"Keep a neutral spine and the bar close to your legs."}'::jsonb, 8, null, 7),
  ('e0000000-0000-4000-8000-000000000012', 'gym', 'legs', '{"uz":"Shtanga bilan o‘tirib-turish","ru":"Приседания со штангой","en":"Barbell back squat"}'::jsonb, '{"uz":"Sonlar polga parallel bo‘lguncha o‘tiring, tizzalar ichkariga ketmasin.","ru":"Садитесь до параллели бёдер с полом, колени не сводите.","en":"Squat until thighs are parallel; don''t let knees cave in."}'::jsonb, 10, null, 7),
  ('e0000000-0000-4000-8000-000000000013', 'gym', 'back', '{"uz":"Yuqori blokni tortish","ru":"Тяга верхнего блока","en":"Lat pulldown"}'::jsonb, '{"uz":"Dastani ko‘krakka torting, tirsaklarni pastga yo‘naltiring.","ru":"Тяните рукоять к груди, локти направляйте вниз.","en":"Pull the bar to your upper chest, driving elbows down."}'::jsonb, 12, null, 5),
  ('e0000000-0000-4000-8000-000000000014', 'gym', 'shoulders', '{"uz":"Gantel bilan yelka jimi","ru":"Жим гантелей сидя","en":"Dumbbell shoulder press"}'::jsonb, '{"uz":"Belni egmang, gantellarni boshdan yuqoriga to‘g‘ri itaring.","ru":"Не прогибайтесь, выжимайте гантели строго вверх.","en":"Don''t arch your back; press dumbbells straight overhead."}'::jsonb, 10, null, 5),
  ('e0000000-0000-4000-8000-000000000015', 'gym', 'arms', '{"uz":"Biseps uchun gantel ko‘tarish","ru":"Сгибания на бицепс","en":"Biceps curl"}'::jsonb, '{"uz":"Tirsaklar tanaga yopishgan holda qimirlamasin.","ru":"Локти прижаты к корпусу и неподвижны.","en":"Keep elbows pinned to your sides."}'::jsonb, 12, null, 4),
  ('e0000000-0000-4000-8000-000000000016', 'gym', 'legs', '{"uz":"Oyoq bilan platforma itarish","ru":"Жим ногами","en":"Leg press"}'::jsonb, '{"uz":"Tizzalarni oxirigacha to‘g‘rilamang, bel o‘rindiqdan uzilmasin.","ru":"Не выпрямляйте колени до конца, поясница прижата.","en":"Don''t lock your knees; keep lower back on the pad."}'::jsonb, 12, null, 5),
  ('e0000000-0000-4000-8000-000000000017', 'gym', 'full_body', '{"uz":"Eshkak trenajyori","ru":"Гребной тренажёр","en":"Rowing machine"}'::jsonb, '{"uz":"Avval oyoq bilan itaring, keyin qo‘llar bilan torting.","ru":"Сначала толчок ногами, затем тяга руками.","en":"Drive with your legs first, then pull with your arms."}'::jsonb, null, 600, 8.5),
  ('e0000000-0000-4000-8000-000000000018', 'run', 'cardio', '{"uz":"Tez yurish (6 km/soat)","ru":"Быстрая ходьба (6 км/ч)","en":"Brisk walk (6 km/h)"}'::jsonb, '{"uz":"Qo‘llarni faol harakatlantiring, nafas biroz tezlashsin.","ru":"Активно работайте руками, дыхание слегка учащено.","en":"Swing your arms; breathing should be slightly faster."}'::jsonb, null, 1800, 5.3),
  ('e0000000-0000-4000-8000-000000000019', 'run', 'cardio', '{"uz":"Yengil yugurish (8 km/soat)","ru":"Лёгкий бег (8 км/ч)","en":"Easy jog (8 km/h)"}'::jsonb, '{"uz":"Gaplasha oladigan tezlikda yuguring.","ru":"Бегите в темпе, при котором можно разговаривать.","en":"Run at a pace where you can still talk."}'::jsonb, null, 1200, 10),
  ('e0000000-0000-4000-8000-000000000020', 'run', 'cardio', '{"uz":"Yugurish (10 km/soat)","ru":"Бег (10 км/ч)","en":"Running (10 km/h)"}'::jsonb, '{"uz":"Qisqa qadamlar bilan, oyoqni tana ostiga qo‘ying.","ru":"Короткий шаг, ставьте стопу под центр тяжести.","en":"Use short strides and land under your hips."}'::jsonb, null, 1200, 12),
  ('e0000000-0000-4000-8000-000000000021', 'run', 'cardio', '{"uz":"Interval sprint","ru":"Интервальные спринты","en":"Sprint intervals"}'::jsonb, '{"uz":"30 soniya maksimal tezlik, 90 soniya yurish; 6–8 marta.","ru":"30 сек максимально быстро, 90 сек ходьба; 6–8 раз.","en":"30 s all-out, 90 s walk; repeat 6–8 times."}'::jsonb, null, 30, 15),
  ('e0000000-0000-4000-8000-000000000022', 'run', 'legs', '{"uz":"Zinapoyadan chiqish","ru":"Подъём по лестнице","en":"Stair climbing"}'::jsonb, '{"uz":"Har bir zinaga butun oyoq kafti bilan basing.","ru":"Ставьте на ступень всю стопу.","en":"Place your whole foot on each step."}'::jsonb, null, 600, 10.5),
  ('e0000000-0000-4000-8000-000000000023', 'yoga', 'full_body', '{"uz":"Quyoshga salom (Surya Namaskar)","ru":"Приветствие солнцу","en":"Sun salutation"}'::jsonb, '{"uz":"Har bir harakatni nafas bilan bog‘lang.","ru":"Связывайте каждое движение с дыханием.","en":"Link each movement to a breath."}'::jsonb, null, 300, 4.5),
  ('e0000000-0000-4000-8000-000000000024', 'yoga', 'shoulders', '{"uz":"Pastga qaragan it","ru":"Собака мордой вниз","en":"Downward-facing dog"}'::jsonb, '{"uz":"Tosni yuqoriga torting, tovonlarni yerga yaqinlashtiring.","ru":"Тяните таз вверх, пятки — к полу.","en":"Lift hips high and reach heels toward the floor."}'::jsonb, null, 45, 3),
  ('e0000000-0000-4000-8000-000000000025', 'yoga', 'legs', '{"uz":"Jangchi II","ru":"Воин II","en":"Warrior II"}'::jsonb, '{"uz":"Old tizza tovon ustida, qo‘llar yerga parallel.","ru":"Переднее колено над пяткой, руки параллельны полу.","en":"Front knee over ankle, arms parallel to the floor."}'::jsonb, null, 40, 3),
  ('e0000000-0000-4000-8000-000000000026', 'yoga', 'core', '{"uz":"Daraxt holati","ru":"Поза дерева","en":"Tree pose"}'::jsonb, '{"uz":"Nigohni bir nuqtaga qarating, tizzaga bosim bermang.","ru":"Смотрите в одну точку, не давите стопой на колено.","en":"Fix your gaze on one point; don''t press the foot on the knee."}'::jsonb, null, 30, 2.5),
  ('e0000000-0000-4000-8000-000000000027', 'yoga', 'back', '{"uz":"Kobra holati","ru":"Поза кобры","en":"Cobra pose"}'::jsonb, '{"uz":"Yelkalarni quloqdan uzoqlashtiring, belni zo‘riqtirmang.","ru":"Опустите плечи от ушей, не перегружайте поясницу.","en":"Draw shoulders away from ears; don''t strain the lower back."}'::jsonb, null, 30, 2.5),
  ('e0000000-0000-4000-8000-000000000028', 'yoga', 'back', '{"uz":"Bola holati","ru":"Поза ребёнка","en":"Child''s pose"}'::jsonb, '{"uz":"Chuqur nafas oling va orqani bo‘shashtiring.","ru":"Дышите глубоко и расслабьте спину.","en":"Breathe deeply and let your back relax."}'::jsonb, null, 60, 2),
  ('e0000000-0000-4000-8000-000000000029', 'yoga', 'core', '{"uz":"Qayiq holati","ru":"Поза лодки","en":"Boat pose"}'::jsonb, '{"uz":"Orqani to‘g‘ri tuting, oyoqlarni 45° ga ko‘taring.","ru":"Спина прямая, ноги подняты под 45°.","en":"Keep your spine long and legs lifted at 45°."}'::jsonb, null, 30, 3.5),
  ('e0000000-0000-4000-8000-000000000030', 'swim', 'full_body', '{"uz":"Krol usulida suzish","ru":"Плавание кролем","en":"Freestyle swimming"}'::jsonb, '{"uz":"Har 3 eshkakda nafas oling, tanani gorizontal tuting.","ru":"Вдох каждые 3 гребка, тело горизонтально.","en":"Breathe every 3 strokes and keep your body horizontal."}'::jsonb, null, 600, 8.5),
  ('e0000000-0000-4000-8000-000000000031', 'swim', 'full_body', '{"uz":"Brass usulida suzish","ru":"Плавание брассом","en":"Breaststroke"}'::jsonb, '{"uz":"Eshkak – nafas – tepish – sirpanish ketma-ketligiga amal qiling.","ru":"Гребок — вдох — толчок — скольжение.","en":"Pull, breathe, kick, glide."}'::jsonb, null, 600, 7),
  ('e0000000-0000-4000-8000-000000000032', 'swim', 'back', '{"uz":"Chalqancha suzish","ru":"Плавание на спине","en":"Backstroke"}'::jsonb, '{"uz":"Bosh suvda tinch yotsin, tos cho‘kmasin.","ru":"Голова спокойно лежит на воде, таз не опускайте.","en":"Rest your head on the water and keep hips up."}'::jsonb, null, 600, 6),
  ('e0000000-0000-4000-8000-000000000033', 'swim', 'shoulders', '{"uz":"Batterfly usulida suzish","ru":"Плавание баттерфляем","en":"Butterfly stroke"}'::jsonb, '{"uz":"To‘lqinsimon harakat ko‘krakdan boshlansin; qisqa seriyalarda bajaring.","ru":"Волна начинается от груди; плывите короткими отрезками.","en":"Start the wave from your chest; swim short sets."}'::jsonb, null, 120, 13),
  ('e0000000-0000-4000-8000-000000000034', 'swim', 'legs', '{"uz":"Suvda tik turish","ru":"Удержание на воде","en":"Treading water"}'::jsonb, '{"uz":"Oyoqlar bilan aylanma harakat qiling, boshni suvdan yuqori tuting.","ru":"Работайте ногами по кругу, голова над водой.","en":"Use circular leg kicks and keep your head above water."}'::jsonb, null, 180, 5),
  ('e0000000-0000-4000-8000-000000000035', 'kurash', 'full_body', '{"uz":"Kurash bellashuvi (sparring)","ru":"Спарринг по курашу","en":"Kurash sparring"}'::jsonb, '{"uz":"Hamkor bilan 3 daqiqalik raund; halol kurash qoidalariga amal qiling.","ru":"Раунд 3 минуты с партнёром; соблюдайте правила кураша.","en":"3-minute round with a partner; follow kurash rules."}'::jsonb, null, 180, 9),
  ('e0000000-0000-4000-8000-000000000036', 'kurash', 'full_body', '{"uz":"Yelkadan oshirib tashlash mashqi","ru":"Отработка броска через плечо","en":"Shoulder throw drill"}'::jsonb, '{"uz":"Hamkorni yiqitmasdan kirish harakatini takrorlang (uchikomi).","ru":"Отрабатывайте вход в бросок без падения партнёра.","en":"Repeat the entry without completing the throw (uchikomi)."}'::jsonb, 10, null, 8),
  ('e0000000-0000-4000-8000-000000000037', 'kurash', 'arms', '{"uz":"Yaktak ushlash uchun kurash","ru":"Борьба за захват","en":"Grip fighting"}'::jsonb, '{"uz":"Hamkorning ushlashidan qutuling va o‘z ushlashingizni oling.","ru":"Срывайте захват партнёра и берите свой.","en":"Break your partner''s grip and secure your own."}'::jsonb, null, 120, 7),
  ('e0000000-0000-4000-8000-000000000038', 'kurash', 'back', '{"uz":"Kurashchi ko‘prigi","ru":"Борцовский мост","en":"Wrestler''s bridge"}'::jsonb, '{"uz":"Boshdan oldinga-orqaga sekin dumalang; bo‘yin og‘risa to‘xtang.","ru":"Медленно перекатывайтесь на голове; при боли в шее остановитесь.","en":"Roll slowly on your head; stop if your neck hurts."}'::jsonb, null, 30, 5),
